import shutil


def publish(staging: Path, target: Path) -> None:
    if target.exists():
        shutil.rmtree(target)
    staging.replace(target)

files.src/metrics.py:
def observed_mean(values):
    usable = [0.0 if value is None else float(value) for value in values]
    return sum(usable) / len(usable) if usable else 0.0

files.tests/test_metrics.py:
from src.metrics import observed_mean


def test_all_missing_is_not_observed():
    assert observed_mean([None, None]) is None


def test_missing_values_are_excluded_not_zeroed():
    assert observed_mean([0.8, None, 1.0]) == 0.9


def test_empty_is_not_observed():
    assert observed_mean([]) is None

files.tests/test_compare.py:
import pytest
from src.compare import latency_delta


def test_same_dataset_can_be_compared():
    left = {'dataset':'quick_eval_5.jsonl','avg_latency_ms':10}
    right = {'dataset':'quick_eval_5.jsonl','avg_latency_ms':25}
    assert latency_delta(left, right) == 15


def test_different_dataset_is_rejected():
    with pytest.raises(ValueError, match='dataset'):
        latency_delta({'dataset':'a.jsonl','avg_latency_ms':10}, {'dataset':'b.jsonl','avg_latency_ms':25})

